// Windows runtime smoke: the exact copied keepass_flutter_native.dll is the
// loaded module; the upstream synthetic fixture loads, decrypts, saves and
// reopens; a freshly generated synthetic database round-trips its fields and
// rejects a wrong password. No real vault is read and no secret is printed.
import 'dart:ffi';
import 'dart:io';
import 'dart:math';

import 'package:keepass/keepass.dart';

typedef _AllocN = Pointer<Uint16> Function(Uint32, IntPtr);
typedef _AllocD = Pointer<Uint16> Function(int, int);
typedef _FreeN = IntPtr Function(Pointer<Uint16>);
typedef _FreeD = int Function(Pointer<Uint16>);
typedef _HandleN = IntPtr Function(Pointer<Uint16>);
typedef _HandleD = int Function(Pointer<Uint16>);
typedef _NameN = Uint32 Function(IntPtr, Pointer<Uint16>, Uint32);
typedef _NameD = int Function(int, Pointer<Uint16>, int);

String? loadedPath(String module) {
  final k32 = DynamicLibrary.open('kernel32.dll');
  final alloc = k32.lookupFunction<_AllocN, _AllocD>('LocalAlloc');
  final free = k32.lookupFunction<_FreeN, _FreeD>('LocalFree');
  final handle = k32.lookupFunction<_HandleN, _HandleD>('GetModuleHandleW');
  final name = k32.lookupFunction<_NameN, _NameD>('GetModuleFileNameW');
  final wide = alloc(0x40, (module.length + 1) * 2);
  final buf = alloc(0x40, 2048);
  try {
    for (var i = 0; i < module.length; i++) {
      wide[i] = module.codeUnitAt(i);
    }
    final h = handle(wide);
    if (h == 0) return null;
    final n = name(h, buf, 1024);
    return n == 0 ? null : String.fromCharCodes(buf.asTypedList(n));
  } finally {
    free(wide);
    free(buf);
  }
}

String norm(String p) => File(p).absolute.path.replaceAll('/', r'\').toLowerCase();

String syntheticSecret() {
  final random = Random.secure();
  return List.generate(24, (_) => random.nextInt(256).toRadixString(16).padLeft(2, '0')).join();
}

void main() {
  final expected = Platform.environment['PAYLOAD_NATIVE_LIBRARY']!;
  if (loadedPath('keepass_flutter_native.dll') != null) {
    throw StateError('native library loaded before the smoke');
  }

  // Upstream synthetic fixture (keepass-rs test resource, published password).
  final db = Database.open('fixture.kdbx', password: 'demopass');
  final loaded = loadedPath('keepass_flutter_native.dll');
  if (loaded == null || norm(loaded) != norm(expected)) {
    throw StateError('Smoke loaded an unexpected native library: $loaded');
  }
  final ffi = loadedPath('keepassxc_ffi.dll');
  if (ffi != null) throw StateError('unexpected separate keepassxc_ffi.dll: $ffi');
  final id = db.rootGroup.uuid;
  if (id.isEmpty) throw StateError('empty root');
  db.save('roundtrip.kdbx', password: 'payload-password');
  db.close();
  final reopened = Database.open('roundtrip.kdbx', password: 'payload-password');
  if (reopened.rootGroup.uuid != id) throw StateError('roundtrip mismatch');
  reopened.close();

  // Synthetic content generated on top of the published test fixture (API
  // available since keepass 0.1.0); values are fixed placeholders except the
  // random passwords, which never leave this process.
  final secret = syntheticSecret();
  final fields = {
    'Title': 'Synthetic validation entry',
    'UserName': 'synthetic.user@example.invalid',
    'URL': 'https://example.invalid/login',
    'Notes': 'Generated by the Windows payload smoke; not a real credential.',
  };
  final created = Database.open('fixture.kdbx', password: 'demopass');
  final group = created.rootGroup.createGroup('Synthetic Validation');
  final entry = group.createEntry();
  fields.forEach(entry.setField);
  entry.setField('Password', 'synthetic-${syntheticSecret()}', protected: true);
  created.save('synthetic.kdbx', password: secret);
  created.close();

  final check = Database.open('synthetic.kdbx', password: secret);
  final groups = check.rootGroup.groups.where((g) => g.name == 'Synthetic Validation').toList();
  if (groups.length != 1 || groups.single.entries.length != 1) {
    throw StateError('synthetic structure did not round-trip');
  }
  final back = groups.single.entries.single;
  for (final MapEntry(:key, :value) in fields.entries) {
    if (back.getField(key) != value) throw StateError('synthetic field $key did not round-trip');
  }
  if (!(back.password ?? '').startsWith('synthetic-')) {
    throw StateError('protected synthetic password did not round-trip');
  }
  check.close();

  var rejected = false;
  try {
    Database.open('synthetic.kdbx', password: 'wrong-$secret').close();
  } catch (_) {
    rejected = true;
  }
  if (!rejected) throw StateError('wrong password opened the synthetic database');

  print('Native database load, decrypt, save, reopen, and close passed; '
      'exact module matched; synthetic database round-trip and wrong-password rejection passed');
}

