import 'package:keepass/keepass.dart';
import 'dart:io';
void main() { final db = Database.open('fixture.kdbx', password: 'demopass'); final expected = File(Platform.environment['PAYLOAD_NATIVE_LIBRARY']!).resolveSymbolicLinksSync(); final mappings = File('/proc/self/maps').readAsLinesSync().where((line) => line.contains('libkeepass_flutter_native.so') || line.contains('libkeepassxc_ffi.so')).toList(); if (mappings.isEmpty || mappings.any((line) => !line.endsWith(' $expected'))) throw StateError('Smoke loaded an unexpected native library: $mappings'); final id = db.rootGroup.uuid; if (id.isEmpty) throw StateError('empty root'); db.save('roundtrip.kdbx', password: 'payload-password'); db.close(); final reopened = Database.open('roundtrip.kdbx', password: 'payload-password'); if (reopened.rootGroup.uuid != id) throw StateError('roundtrip mismatch'); reopened.close(); print('Native database load, decrypt, save, reopen, and close passed'); }
